/* Offline discussion prototype. No fetch, storage, postMessage, upload or banking API. */
(()=>{
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>(n/100).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
const pages=[['dashboard','Dashboard','财务工作台'],['requests','Payment Requests','付款申请'],['creditor','Creditor','供应商应付'],['debtor','Debtor','客户应收'],['bank','Bank & Cash','银行及现金'],['history','Transaction History','已结交易'],['activity','Activity History','财务活动']];
const seed=[
 {id:'00124',supplier:'KOH SOON HUAT',customer:'SAMPLE',eta:'28 Oct 2026',age:'Today',at:'17 Oct 2026 09:15',by:'PURCHASE DEMO',request:43000,invoice:48000,cn:5000,paid:0,stage:'NEW',purpose:'Full payment 全额付款',term:'30 days',due:'16 Nov 2026',note:'',basis:'INV',docs:true},
 {id:'00125',supplier:'HONG LEA',customer:'SCOMM',eta:'28 Oct 2026',age:'Yesterday',at:'16 Oct 2026 15:20',by:'PURCHASE DEMO',request:120000,invoice:120000,cn:0,paid:0,stage:'REVIEW',purpose:'Deposit 订金',term:'Prepayment 预付',due:'Before shipment',note:'Urgent shipment 急发货',basis:'PI',chase:true},
 {id:'00126',supplier:'KOH SOON HUAT',customer:'SAMPLE',eta:'30 Oct 2026',age:'2 Days ago',at:'15 Oct 2026 11:40',by:'PURCHASE DEMO',request:86000,invoice:96000,cn:10000,paid:0,stage:'PROBLEM',purpose:'Full payment 全额付款',term:'30 days',due:'14 Nov 2026',note:'Supplier reminder 供应商催促',accNote:'Please replace the unclear invoice 请更换不清晰发票',basis:'INV',docs:false},
 {id:'00127',supplier:'HONG LEA',customer:'SCOMM',eta:'27 Oct 2026',age:'3 Days ago',at:'14 Oct 2026 14:05',by:'PURCHASE DEMO',request:200000,invoice:200000,cn:0,paid:80000,stage:'PARTIAL',purpose:'Full payment 全额付款',term:'7 days',due:'21 Oct 2026',note:'',basis:'INV',proof:true,docs:true},
 {id:'00128',supplier:'KOH SOON HUAT',customer:'SAMPLE',eta:'26 Oct 2026',age:'4 Days ago',at:'13 Oct 2026 10:00',by:'PURCHASE DEMO',request:65000,invoice:65000,cn:0,paid:65000,stage:'PAID',purpose:'Balance 尾款',term:'14 days',due:'27 Oct 2026',basis:'INV',proof:true,docs:true,note:'',accNote:'Payment recorded 付款已记录'},
 {id:'00129',supplier:'HONG LEA',customer:'SCOMM',eta:'25 Oct 2026',age:'5 Days ago',at:'12 Oct 2026 16:30',by:'PURCHASE DEMO',request:90000,invoice:90000,cn:0,paid:0,stage:'UNKNOWN',purpose:'Part payment 部分付款',term:'7 days',due:'19 Oct 2026',note:'',basis:'INV',accNote:'Bank result needs confirmation 银行结果待核实'}
];
let requests=structuredClone(seed),events=[],view='dashboard',filter='ALL',query='',company='NCT',proofSelected=false,actionFilter='';
const rows=()=>company==='NCT'?requests:[],status=r=>({NEW:['Waiting for Acc. response','gray'],REVIEW:['🔒 Reviewing Docs','gray'],PROBLEM:['⚠ Problem','red'],PARTIAL:['Partially Paid','orange'],PAID:['Fully Paid','green'],PROCESSING:['Processing 付款处理中','orange'],UNKNOWN:['⚠ Result Unknown','red']}[r.stage]);
const pill=r=>{const [text,tone]=status(r);return '<span class="pill '+tone+'">'+text+'</span>'},po=r=>'NCT-PO-'+r.id;
function showNotice(text){$('#notice').textContent=text;$('#notice').style.display='block';setTimeout(()=>$('#notice').style.display='none',3500);}
function audit(r,action,note){events.unshift({po:po(r),supplier:r.supplier,at:'17 Oct 2026 · Demo time',by:'ACCOUNT DEMO',action,note});}
function title(en,zh,context=''){return '<div class="page-title"><div><h1>'+en+' '+zh+'</h1><p>'+(company==='NCT'?'North Cape Trading Sdn. Bhd.':'Global HR')+'</p></div>'+(context?'<span class="context">'+context+'</span>':'')+'<button class="refresh" data-refresh>Refresh 刷新</button></div>';}
function table(headers,widths,body,foot=''){return '<section class="panel"><div class="table-scroll"><table><colgroup>'+widths.map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup><thead><tr>'+headers.map(([text,cls])=>'<th class="'+(cls||'')+'">'+text+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div><div class="foot"><span>'+foot+'</span><span>'+company+' · 示例数据</span></div></section>';}
const empty=n=>'<tr><td colspan="'+n+'" class="empty">No matching records 没有匹配记录</td></tr>';
const matches=(r,key)=>key==='ALL'||key==='NEW'&&r.stage==='NEW'||key==='CHASE'&&r.chase||key==='ISSUE'&&['PROBLEM','UNKNOWN'].includes(r.stage)||key==='WORK'&&['REVIEW','PARTIAL','PROCESSING'].includes(r.stage);
function cards(){return '<div class="cards">'+[['NEW','New Requests','待财务接手','orange'],['CHASE','Purchase Chase','采购催款','orange'],['ISSUE','Needs Resolution','必须解决','red'],['WORK','In Progress','财务处理中','']].map(([key,en,zh,tone])=>{const count=rows().filter(r=>matches(r,key)).length;return '<button class="task-card '+(count?tone:'')+'" data-queue="'+key+'"><span>'+en+'<small>'+zh+'</small></span><b>'+count+'</b></button>';}).join('')+'</div>';}
function toolbar(placeholder,options=''){return '<div class="toolbar"><input id="search" aria-label="Search records 搜索记录" placeholder="'+placeholder+'" value="'+esc(query)+'">'+options+'<span class="count" id="count"></span></div>';}
function queueTable(list){return table([['Requested'],['P.O. No.'],['Supplier'],['Purchase For'],['Request MYR','numeric'],['Paid MYR','numeric'],['Status'],['Pay Slip','center'],['Note from Purchase'],['Open','center']],[10,11,15,10,9,9,15,5,12,4],list.map(r=>'<tr><td><b>'+r.age+'</b><small>'+r.at+'</small><small>by '+r.by+'</small></td><td><button class="po-link" data-open="'+r.id+'">'+po(r)+'</button></td><td>'+r.supplier+'</td><td><b>'+r.customer+'</b><small>ETA: '+r.eta+'</small></td><td class="numeric"><b>'+money(r.request)+'</b><small>'+r.basis+(r.cn?' · CN −'+money(r.cn):'')+'</small></td><td class="numeric">'+money(r.paid)+'<small>Balance '+money(Math.max(0,r.request-r.paid))+'</small></td><td>'+pill(r)+(r.chase?'<span class="chase" title="Purchase chased 采购已催款">ϟ</span>':'')+'</td><td class="center"><button class="slip" '+(r.proof?'data-proof="'+r.id+'"':'disabled')+' aria-label="'+(r.proof?'View':'Missing')+' pay slip '+po(r)+'">↓</button></td><td>'+esc(r.note||'—')+(r.note?'<small>'+r.by+'</small>':'')+'</td><td class="center"><button class="po-link" data-open="'+r.id+'">→</button></td></tr>').join('')||empty(10),'金额属于本次申请；INV 与 CN 核对不以 PO 参考金额替代。');}
function dashboard(){const work=rows().filter(r=>r.stage!=='PAID');return title('Dashboard','财务工作台')+cards()+toolbar('P.O. · Supplier · Customer')+queueTable(work)+'<div class="split"><section class="panel"><div class="panel-title"><h2>Reconciliation 对账事项</h2></div><div style="padding:0 12px 12px"><p>Final INV missing 最终发票未齐 <b>'+(company==='NCT'?1:0)+'</b></p><p>Receiving discrepancy 收货差异 <b>'+(company==='NCT'?1:0)+'</b></p><p>Supplier credits 待处理供应商贷项 <b>'+(company==='NCT'?1:0)+'</b></p><button data-page="creditor">Open Creditor 进入应付对账 →</button></div></section><section class="panel"><div class="panel-title"><h2>Latest Activity 最近操作</h2><button data-page="activity">View all 查看全部 →</button></div><div style="padding:0 12px 12px">'+activityPreview()+'</div></section></div><p class="legend">橙色需要处理，红色是真实问题，绿色表示对应事项已完成。未提交的 PO 不混入付款申请；历史遗留单据在应付对账中保留独立入口。</p>';}
function payments(){return title('Payment Requests','付款申请')+cards()+toolbar('P.O. · Supplier · Customer','<select id="requestFilter" aria-label="Request status"><option value="ALL">All Requests 全部申请</option>'+[['NEW','Awaiting Review 待接手'],['CHASE','Purchase Chase 采购催款'],['ISSUE','Problems 问题'],['WORK','In Progress 处理中']].map(([k,t])=>'<option value="'+k+'" '+(filter===k?'selected':'')+'>'+t+'</option>').join('')+'</select>')+queueTable(rows().filter(r=>matches(r,filter)))+'<p class="legend">点击申请进入同一处理窗口。Reviewing 接手后锁定采购修改；退回前须确认没有处理中或结果未知的付款。</p>';}
function creditor(){const list=rows().filter(r=>r.basis==='INV'&&r.stage!=='PAID');return title('Creditor','供应商应付')+toolbar('Supplier · INV · P.O.')+table([['Supplier'],['Invoice'],['P.O. No.'],['INV MYR','numeric'],['CN MYR','numeric'],['Paid MYR','numeric'],['Balance MYR','numeric'],['Due'],['Reconciliation']],[15,12,12,9,8,9,10,10,15],list.map(r=>'<tr><td><b>'+r.supplier+'</b></td><td>INV-'+r.id+'</td><td><button class="po-link" data-open="'+r.id+'">'+po(r)+'</button></td><td class="numeric">'+money(r.invoice)+'</td><td class="numeric">'+money(r.cn)+'</td><td class="numeric">'+money(r.paid)+'</td><td class="numeric"><b>'+money(r.invoice-r.cn-r.paid)+'</b></td><td>'+r.due+'</td><td>'+pill(r)+'</td></tr>').join('')||empty(9),'应付余额来自最终 INV、适用 CN、已登记付款及已应用贷项；同一 PO 不重复记账。')+'<div class="split"><section class="panel"><div class="panel-title"><h2>Supplier Credit 供应商贷项余额</h2></div><div style="padding:0 12px 12px">'+(company==='NCT'?'<b>HONG LEA · MYR 50.00</b><p>CN-DEMO-09 · 已确认可用贷项</p><button data-credit>Review credit 查看贷项使用</button>':'No supplier credit 暂无贷项')+'</div></section><section class="panel"><div class="panel-title"><h2>Legacy & Exceptions 历史遗留与异常</h2></div><div style="padding:0 12px 12px">'+(company==='NCT'?'<p>1 个旧 PO 有付款记录，尚无完整新申请。</p><button data-legacy>Reconcile legacy 核对旧单</button>':'No legacy issues 暂无遗留异常')+'</div></section></div>';}
function debtor(){const list=company==='NCT'?[['SCOMM','SI-DEMO-001','MYR',540000,300000,'24 Oct 2026'],['SAMPLE','SI-DEMO-002','MYR',96000,0,'30 Oct 2026'],['SCOMM EXPORT','SI-DEMO-003','SGD',120000,0,'28 Oct 2026']]:[];return title('Debtor','客户应收')+toolbar('Customer · Sales Invoice')+'<div class="money-cards">'+['MYR','SGD'].map(currency=>'<section class="money-card"><span>'+currency+' Outstanding 应收余额</span><b>'+(company==='NCT'?money(list.filter(r=>r[2]===currency).reduce((n,r)=>n+r[3]-r[4],0)):'—')+'</b><small>各币种独立显示，不混加</small></section>').join('')+'</div>'+table([['Customer'],['Sales Invoice'],['Currency'],['Invoice Amount','numeric'],['Received','numeric'],['Balance','numeric'],['Due'],['Open']],[20,16,8,12,12,12,12,8],list.map(r=>'<tr><td><b>'+r[0]+'</b></td><td>'+r[1]+'</td><td>'+r[2]+'</td><td class="numeric">'+money(r[3])+'</td><td class="numeric">'+money(r[4])+'</td><td class="numeric"><b>'+money(r[3]-r[4])+'</b></td><td>'+r[5]+'</td><td><button class="po-link" data-debtor="'+r[1]+'">View 查看 →</button></td></tr>').join('')||empty(8),'Sales INV、客户 CN、Debit Note 与收款记录共同决定余额。')+'<p class="legend">客户应收与供应商应付分开。这里的收款登记不改变销售发票的成本或 GP 冻结记录。</p>';}
function bank(){const total=rows().filter(r=>!['PROBLEM','UNKNOWN'].includes(r.stage)).reduce((n,r)=>n+Math.max(0,r.request-r.paid),0);return title('Bank & Cash','银行及现金')+'<div class="money-cards">'+[[company==='NCT'?'MYR 82,450.00':'—','Recorded balance 登记余额','示例 · 17 Oct 2026 09:00'],['MYR '+money(total),'Outstanding requests 未付申请','按当前申请示例合计，不等于已获批付款'],[company==='NCT'?'MYR 16,000.00':'—','Expected collections 预计收款','示例预测，不计入实际银行余额']].map(([a,b,c])=>'<section class="money-card"><span>'+b+'</span><b>'+a+'</b><small>'+c+'</small></section>').join('')+'</div>'+toolbar('Bank · Reference · P.O.')+table([['Recorded At'],['Bank Account'],['Direction'],['Reference'],['P.O. No.'],['Currency'],['Amount','numeric'],['Recorded By'],['Proof']],[13,15,9,15,13,7,12,10,6],company==='NCT'?'<tr><td>17 Oct 2026 09:00</td><td>Maybank · ••••1208</td><td>Opening 期初</td><td>BALANCE-DEMO</td><td>—</td><td>MYR</td><td class="numeric">82,450.00</td><td>ACCOUNT DEMO</td><td><button data-bank>View</button></td></tr><tr><td>16 Oct 2026 14:30</td><td>Maybank · ••••1208</td><td>Payment 付款</td><td>PAY-DEMO-127</td><td>NCT-PO-00127</td><td>MYR</td><td class="numeric">−800.00</td><td>ACCOUNT DEMO</td><td><button class="slip" data-proof="00127">↓</button></td></tr>':empty(9),'余额来源、登记人和时间必须可追溯。预测和实际记录分开。')+'<div class="callout warning">余额取得方式、银行账户与登记权限待确认。草稿不连接银行，也不会把“标记处理中”当成已经付款。</div>';}
function history(){return title('Transaction History','已结交易')+toolbar('P.O. · Supplier · INV','<select aria-label="History year"><option>2026</option></select><select aria-label="History month"><option>October 十月</option><option>All months 全部月份</option></select>')+table([['Completed'],['P.O. No.'],['Supplier'],['Purchase For'],['Net MYR','numeric'],['Settlement'],['Pay Slip','center'],['Files'],['History']],[12,14,18,12,11,12,6,8,7],company==='NCT'?'<tr><td><b>15 Oct 2026</b><small>by ACCOUNT DEMO</small></td><td><button class="po-link" data-closed>NCT-PO-00110</button></td><td>HONG LEA</td><td>SCOMM</td><td class="numeric"><b>1,520.00</b></td><td><span class="pill green">Checked 已核齐</span></td><td class="center"><button class="slip" data-closed>↓</button></td><td><button data-closed>PO · INV · DO · CN</button></td><td><button data-closed>History</button></td></tr>':empty(9),'保留整单记录、付款凭证和所有财务动作，不删除历史。')+'<div class="callout">进入已结交易须满足现有规则：款项结清、必需文件和 CN 处理齐全、收货异常解决、财务 Checked 有效，以及客户 Sales Invoice 已齐。单纯 Fully Paid 不等于整单结案。</div>';}
const baseEvents=()=>company==='NCT'?[{po:'NCT-PO-00128',supplier:'KOH SOON HUAT',at:'16 Oct 2026 14:35',by:'ACCOUNT DEMO',action:'Payment recorded 记录付款',note:'MYR 650.00 · PAY-DEMO-128'},{po:'NCT-PO-00125',supplier:'HONG LEA',at:'16 Oct 2026 10:15',by:'ACCOUNT DEMO',action:'Reviewing 接手并锁定',note:'采购申请进入财务核单'},{po:'NCT-PO-00126',supplier:'KOH SOON HUAT',at:'15 Oct 2026 16:40',by:'ACCOUNT DEMO',action:'Returned 退回采购',note:'发票不清晰，待重新上载'}]:[];
const activityPreview=()=>[...events,...baseEvents()].slice(0,3).map(e=>'<p><b>'+e.action+'</b><br><small>'+e.po+' · '+e.at+'</small></p>').join('')||'<p>No activity 暂无操作</p>';
function activity(){const list=[...events,...baseEvents()];return title('Activity History','财务活动')+toolbar('P.O. · Staff · Action','<select id="activityAction" aria-label="Action filter"><option>All Actions 全部操作</option><option>Reviewing</option><option>Payment</option><option>Returned</option></select>')+table([['Date & Time'],['Staff'],['Action'],['Reference'],['Details']],[16,14,24,20,26],list.map(e=>'<tr><td>'+e.at+'</td><td>'+e.by+'</td><td><b>'+e.action+'</b></td><td>'+e.po+'<small>'+e.supplier+'</small></td><td>'+esc(e.note)+'</td></tr>').join('')||empty(5),'核单、接手、退回、金额和 CN 确认、凭证、付款结果及结案均记录时间、员工和原因。');}
function render(){if($('#detail').open)$('#detail').close();$('#nav').innerHTML=pages.map(([key,en,zh])=>'<button data-page="'+key+'" class="'+(view===key?'active':'')+'" '+(view===key?'aria-current="page"':'')+'>'+en+'<small>'+zh+'</small></button>').join('');$('#draftApp').innerHTML=({dashboard,payments,requests:payments,creditor,debtor,bank,history,activity}[view]||dashboard)();applySearch();}
function applySearch(){const tr=[...document.querySelectorAll('#draftApp tbody tr')].filter(r=>!r.querySelector('.empty'));let n=0;for(const row of tr){row.hidden=!row.textContent.toLowerCase().includes(query.trim().toLowerCase())||(view==='activity'&&actionFilter&&!row.textContent.toLowerCase().includes(actionFilter));if(!row.hidden)n++;}const count=$('#count');if(count)count.textContent=n+' record'+(n===1?'':'s');let no=$('#noSearch');if(no)no.remove();if(!n&&tr.length){const body=$('#draftApp tbody');if(body)body.insertAdjacentHTML('beforeend','<tr id="noSearch"><td colspan="'+$('#draftApp thead tr').children.length+'" class="empty">No matching records 没有匹配记录</td></tr>');}}
function modal(r,heading,body,actions=''){const closed=!r;$('#detailTitle').innerHTML='<h2>'+esc(r?r.supplier:'Account 财务')+'</h2><p>'+heading+'</p><small>'+esc(r?company+' · '+po(r):'Discussion draft 讨论草稿')+'</small>';$('#detailBody').innerHTML=body;$('#detailActions').innerHTML='<button data-dismiss>Close 关闭</button>'+actions;$('#detail').showModal();}
function detail(r){const remaining=Math.max(0,r.request-r.paid),locked=r.stage!=='NEW';modal(r,'Payment Request 付款申请','<div class="facts">'+[['Requested 申请',r.request],['Paid 已付',r.paid],['Remaining 尚欠',remaining],['CN 贷项',r.cn]].map(([label,n])=>'<div><small>'+label+' MYR</small><b>'+money(n)+'</b></div>').join('')+'</div><p>'+pill(r)+' <span style="margin-left:10px">'+(locked?'🔒 采购端已锁定；退回后方可编辑。':'采购员仍可编辑，财务接手后即锁定。')+'</span></p><div class="fields"><div><small>Requested 提交时间</small><p>'+r.at+' · '+r.by+'</p></div><div><small>Purchase For 采购用途</small><p>'+r.customer+' · ETA '+r.eta+'</p></div><div><small>Purpose 付款用途</small><p>'+r.purpose+'</p></div><div><small>Term 账期</small><p>'+r.term+' · '+r.due+'</p></div></div>'+(r.note?'<div class="request-note"><b>Note from Purchase 采购留言</b><p>'+esc(r.note)+'</p></div>':'')+'<h3 class="section-heading">Supporting Documents 支持文件</h3><table><thead><tr><th>Document</th><th class="numeric">Amount MYR</th><th>Check</th></tr></thead><tbody><tr><td>Our PO · '+po(r)+'</td><td class="numeric">Reference 参考</td><td><button data-demo-doc>View 查看</button></td></tr><tr><td>'+r.basis+' · '+r.basis+'-'+r.id+'</td><td class="numeric">'+money(r.invoice)+'</td><td><button data-demo-doc>View 查看</button></td></tr>'+(r.cn?'<tr><td>CN · CN-'+r.id+'</td><td class="numeric">−'+money(r.cn)+'</td><td>Deduct 本次扣减</td></tr>':'')+'</tbody></table><h3 class="section-heading">Note from Account 财务留言</h3><p>'+esc(r.accNote||'No note yet 暂无留言')+'</p><h3 class="section-heading">History 操作记录</h3><div class="timeline"><p>Request submitted 采购提交<small>'+r.at+' · '+r.by+'</small></p>'+events.filter(e=>e.po===po(r)).map(e=>'<p>'+e.action+'<small>'+e.at+' · '+e.by+'</small>'+esc(e.note)+'</p>').join('')+'</div>',r.stage==='NEW'?'<button class="btn-primary" data-take="'+r.id+'">Reviewing 接手并锁定</button>':r.stage==='UNKNOWN'?'<button class="btn-action problem" data-resolve="'+r.id+'">Resolve bank result 核实银行结果</button>':r.stage==='PAID'?'<button data-reconcile="'+r.id+'">Review closeout 查看结案条件</button>':r.stage==='PROBLEM'?'<button data-problem>Awaiting Purchase 等采购补件</button>':r.stage==='PROCESSING'?'<button class="btn-primary" data-record-open="'+r.id+'">Record Bank Result 登记银行结果</button>':'<button data-return="'+r.id+'">Return to Purchase 退回采购</button><button class="btn-primary" '+(r.reviewed?'data-start-payment':'data-review')+'="'+r.id+'">'+(r.reviewed?'Mark Processing 确认开始银行付款':'Review Payment 核对申请')+'</button>');}
function review(r){modal(r,'Review Payment 核对本次付款申请','<div class="callout">核对申请版本、支持文件和 CN 处理；核单完成不会自动记为已付款。</div><div class="checklist"><label><input type="checkbox" class="review-check"> Supplier and bank details 供应商及收款资料正确</label><label><input type="checkbox" class="review-check"> '+r.basis+' amount and current version 金额与版本已核对</label><label><input type="checkbox" class="review-check"> CN treatment and paid balance 贷项与已付款未重复扣减</label></div><h3 class="section-heading">Note from Account 财务留言</h3><textarea id="reviewNote" rows="2" placeholder="Reconciliation note 核单说明"></textarea>','<button class="btn-primary" data-ready="'+r.id+'">Confirm review 确认核单</button>');}
function record(r){proofSelected=false;modal(r,'Record Payment 登记已发生的付款','<div class="callout warning">此处登记银行已完成的结果及凭证，不执行转账。草稿按钮仅模拟登记。</div><div class="fields"><label>Paid Amount MYR 付款金额<input id="paidAmount" type="number" step="0.01" min="0.01" value="'+((r.request-r.paid)/100).toFixed(2)+'"></label><label>Bank Reference 银行参考号<input id="paidReference" value="PAY-DEMO-'+r.id+'"></label></div><p><button id="demoProof">Use demo pay slip 使用示例付款凭证</button><span id="proofState" style="margin-left:10px">No proof 尚无凭证</span></p><textarea id="paidNote" rows="2" placeholder="Note from Account 财务留言"></textarea>','<button class="btn-green" data-record="'+r.id+'">Record demo payment 记录示例付款</button>');}
function gates(r){modal(r,'Transaction Closeout 交易结案条件','<div class="gate"><span class="done">✓</span> Supplier payment settled 供应商款项已结清</div>'+[['Final Invoice and DO 最终发票与送货单',true],['CN handled or marked not applicable 贷项已处理',true],['Warehouse and shortage resolved 收货及差异已解决',false],['Current Finance Checked 财务最终核对有效',false],['Customer Sales Invoice 客户销售发票齐全',false]].map(([label,done])=>'<div class="gate"><span class="'+(done?'done':'pending')+'">'+(done?'✓':'○')+'</span>'+label+'</div>').join('')+'<div class="callout">Fully Paid 只表示本次申请已付款，缺少上述条件仍留在工作列表。</div>');}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;applySearch();}});
document.addEventListener('change',e=>{if(e.target.id==='company'){company=e.target.value;query='';events=[];render();}if(e.target.id==='requestFilter'){filter=e.target.value;query='';render();}if(e.target.id==='activityAction'){actionFilter=e.target.selectedIndex?e.target.value.toLowerCase():'';applySearch();}});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset,id=d.open||d.take||d.review||d.ready||d.return||d.record||d.proof||d.reconcile||d.resolve,r=rows().find(r=>r.id===id);
 if(d.page){view=d.page;query='';filter='ALL';actionFilter='';render();return;}if(d.queue){view='requests';query='';filter=d.queue;render();return;}if(b.id==='reset'){requests=structuredClone(seed);events=[];query='';filter='ALL';render();showNotice('Demo reset 示例已重置');return;}if(b.id==='close'||'dismiss'in d){$('#detail').close();return;}if('refresh'in d){showNotice('Demo data refreshed 示例数据已刷新');return;}
 if(d.open&&r){detail(r);return;}if(d.take&&r){r.stage='REVIEW';audit(r,'Reviewing 接手并锁定','采购端从此不可编辑，直到财务确认退回。');render();detail(r);return;}if(d.review&&r){review(r);return;}
 if(d.ready&&r){if([...document.querySelectorAll('.review-check')].some(c=>!c.checked)){showNotice('Complete all checks 请完成全部核对');return;}r.accNote=$('#reviewNote').value||'Payment request verified 付款申请已核对';r.reviewed=true;audit(r,'Payment reviewed 确认核单',r.accNote);render();detail(r);return;}
 if(d.startPayment){const row=rows().find(r=>r.id===d.startPayment);modal(row,'Payment Processing 银行付款处理中','<div class="callout warning">仅在已开始真实银行付款时登记处理中。这个状态不表示已付款；处理中禁止重复付款或退回采购。</div><label><input id="bankClear" type="checkbox"> No unresolved previous payment 已确认没有前次未决银行付款</label>','<button class="btn-action" data-processing-confirm="'+row.id+'">Confirm demo processing 确认示例处理中</button>');return;}
 if(d.processingConfirm){const row=rows().find(r=>r.id===d.processingConfirm);if(!$('#bankClear').checked){showNotice('Confirm bank status 请确认银行状态');return;}row.stage='PROCESSING';audit(row,'Payment processing 银行付款处理中','示例登记已开始处理，不表示付款完成。');render();detail(row);return;}
 if(d.recordOpen){record(rows().find(r=>r.id===d.recordOpen));return;}
 if(b.id==='demoProof'){proofSelected=true;$('#proofState').textContent='✓ Demo PDF ready 示例凭证已备妥';return;}
 if(d.record&&r){const cents=Math.round(Number($('#paidAmount').value)*100);if(!r.reviewed||!proofSelected||!(cents>0)||cents>r.request-r.paid||!$('#paidReference').value.trim()){showNotice('Check amount, reference and proof 请核对金额、参考号及凭证');return;}r.paid+=cents;r.proof=true;r.stage=r.paid>=r.request?'PAID':'PARTIAL';r.accNote=$('#paidNote').value||'Payment proof recorded 付款凭证已登记';audit(r,'Payment recorded 记录付款','MYR '+money(cents)+' · '+$('#paidReference').value);render();detail(r);return;}
 if(d.return&&r){modal(r,'Return to Purchase 退回采购','<div class="callout warning">仅在没有银行处理中或结果未知时允许退回。退回必须说明原因，原申请和财务操作仍保留。</div><label>Reason 原因<textarea id="returnNote" rows="3" placeholder="Please explain 请填写原因"></textarea></label>','<button class="btn-action problem" data-return-confirm="'+r.id+'">Confirm demo return 确认示例退回</button>');return;}
 if(d.returnConfirm){const row=rows().find(r=>r.id===d.returnConfirm),note=$('#returnNote').value.trim();if(!note){showNotice('Reason required 请填写退回原因');return;}row.stage='PROBLEM';row.accNote=note;audit(row,'Returned 退回采购',note);render();detail(row);return;}
 if(d.resolve&&r){modal(r,'Resolve Bank Result 核实银行结果','<div class="callout problem">银行结果未确认时，不允许重复发起付款或退回采购。</div><p>草稿演示：核对银行后确认“未付款”，恢复核单队列；真实已付款须关联本次凭证。</p>','<button class="btn-primary" data-not-paid="'+r.id+'">Demo: confirmed unpaid 示例确认未付款</button>');return;}
 if(d.notPaid){const row=rows().find(r=>r.id===d.notPaid);row.stage='REVIEW';audit(row,'Bank result resolved 核实银行结果','示例：确认未付款，可重新核单。');render();detail(row);return;}
 if(d.reconcile&&r){gates(r);return;}if(d.proof){modal(r,'Pay Slip 付款凭证','<div class="callout">示例付款凭证预览。正式版沿用现有文件 VIEW 入口，在 Google Drive 查看对应凭证。</div><p><b>PAY-DEMO-'+id+'</b></p><p>PDF · Uploaded by ACCOUNT DEMO</p>');return;}
 if('demoDoc'in d){showNotice('Demo document only 示例文件入口');return;}
 if('closed'in d){modal(null,'Completed Transaction 已结交易','<p><b>NCT-PO-00110 · HONG LEA</b></p><div class="facts"><div><small>Net MYR</small><b>1,520.00</b></div><div><small>Paid MYR</small><b>1,520.00</b></div></div><p><span class="pill green">Checked 已核齐</span></p><p>Our PO · INV · DO · CN · Pay Slip</p><div class="timeline"><p>Finance Checked 最终核对<small>15 Oct 2026 16:20 · ACCOUNT DEMO</small></p><p>Payment recorded 付款登记<small>15 Oct 2026 15:45 · ACCOUNT DEMO</small></p></div>');return;}
 if(d.debtor){modal(null,'Customer Ledger 客户账目','<p><b>'+esc(d.debtor)+'</b></p><p>Sales Invoice → Receipts 收款 → CN 或 Debit Note 调整 → 剩余应收</p><div class="callout">展开后显示原发票、每笔收款凭证及余额变化。这里仅为草稿，收款不混入供应商付款。</div>');return;}
 if('credit'in d){modal(null,'Supplier Credit 供应商贷项','<p>HONG LEA · CN-DEMO-09 · MYR 50.00</p><div class="callout">只能用于同公司、同供应商的符合条件采购单。应用金额、目标 PO、财务员工及时间全部留痕；不能在两个 PO 重复扣减。</div>');return;}
 if('legacy'in d){modal(null,'Legacy Reconciliation 历史遗留核对','<p>旧 PO 与现有付款记录保留。</p><div class="callout warning">先核对真实银行结果、已有凭证与供应商余额，再沿用现有财务接手流程，不能把旧单自动当作新的未付款申请。</div>');return;}
 if('bank'in d){showNotice('Recorded balance source 待确认余额来源及登记流程');return;}if('problem'in d)showNotice('Waiting for corrected documents 等采购重新提交正确文件');
});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();});render();
})();
